protected int removeUnusedNodes(){
    // Assume Category is a class with properties IsActive and Parent
    int nodesRemoved = 0;

    // Depth-first search to remove inactive nodes
    Stack<Category> stack = new Stack<Category>();
    stack.push(this); // Start from the root category

    while (!stack.isEmpty()) {
        Category current = stack.pop();

        if (!current.IsActive) {
            // Remove node and decrement node count
            if (current.Parent != null) {
                current.Parent.Children.Remove(current);
            }
            nodesRemoved++;
        } else {
            // Push children to stack for further processing
            foreach (Category child in current.Children) {
                stack.Push(child);
            }
        }
    }

    return nodesRemoved;
}

