public long readRawVarint64(InputStream stream) throws IOException {
    long result = 0;
    for (int shift = 0; shift < 64; shift += 7) {
        int b = stream.read();
        if (b == -1) {
            throw new IOException("Unexpected end of stream");
        }
        result |= ((b & 0x7F) << shift);
        if ((b & 0x80) == 0) {
            return result;
        }
    }
    throw new IOException("Malformed Varint");
}

